class Solution {
public:
    int magicalString(int n) {
        if (n <= 0) return 0;
        if (n <= 3) return 1;
        vector<int> s = {1, 2, 2};
        int head = 2;
        while ((int)s.size() < n) {
            int nextVal = 3 - s.back();
            int count = s[head++];
            while (count--) {
                s.push_back(nextVal);
            }
        }
        int ones = 0;
        for (int i = 0; i < n; i++) {
            if (s[i] == 1) ones++;
        }
        return ones;
    }
};

class Solution {
    public int magicalString(int n) {
        if (n <= 0) return 0;
        if (n <= 3) return 1;
        int[] s = new int[n + 2];
        s[0] = 1; s[1] = 2; s[2] = 2;
        int head = 2, tail = 3, num = 1;
        int ones = 1;
        while (tail < n) {
            for (int i = 0; i < s[head]; i++) {
                s[tail] = num;
                if (num == 1 && tail < n) ones++;
                tail++;
            }
            num ^= 3;
            head++;
        }
        return ones;
    }
}

var magicalString = function(n) {
    if (n <= 0) return 0;
    if (n <= 3) return 1;
    const s = [1, 2, 2];
    let head = 2;
    while (s.length < n) {
        const nextVal = 3 - s[s.length - 1];
        const count = s[head++];
        for (let i = 0; i < count; i++) {
            s.push(nextVal);
        }
    }
    let ones = 0;
    for (let i = 0; i < n; i++) {
        if (s[i] === 1) ones++;
    }
    return ones;
};
